def f(n):
    def factorial(num):
        if num == 0:
            return 1
        else:
            return num * factorial(num - 1)

    def sum_of_integers(num):
        return sum(range(1, num + 1))

    if n == 0:
        return []
    elif n == 1:
        return [1]

    result = []
    for i in range(1, n + 1):
        if i % 2 == 0:
            result.append(factorial(i))
